coding.solution:
def client_action(status, headers):
    if 200 <= status < 300:
        return 'done'
    if status == 401:
        return 'reauth'
    if status in (429, 502, 503, 504):
        lower = {k.lower(): v for k, v in headers.items()}
        ra = lower.get('retry-after')
        return ('retry', int(ra) if ra is not None else None)
    return 'fail'
